<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Categories & Brands</title><style>body{font:15px Arial;background:#f4f6fa;color:#172b43}.wrap{max-width:1250px;margin:30px auto;padding:0 15px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#fff;padding:20px;border-radius:12px;margin:15px 0;overflow:auto}input{padding:9px;border:1px solid #ccd5df;border-radius:6px;width:100%;margin:4px 0}button,a{background:#173d65;color:#fff;padding:8px 12px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #eee;font-size:13px}.muted{color:#718096}.active{color:#18794e}.inactive{color:#a45b18}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Product Categories & Brands</h1><p><a href="{{ route('products.index') }}">Back to Products</a> <a href="{{ route('dashboard') }}">Dashboard</a></p>@if(session('success'))<p class="active">{{ session('success') }}</p>@endif @foreach($errors->all() as $e)<p class="inactive">{{ $e }}</p>@endforeach<div class="grid"><section class="card"><h2>Categories</h2><table><tr><th>Name / Description</th><th>Products</th><th>Status</th><th>Actions</th></tr>@forelse($categories as $c)<tr><td>@if(auth()->user()->hasPermission('products.edit'))<form method="POST" action="{{ route('catalog.categories.update',$c) }}">@csrf @method('PUT')<input name="name" value="{{ $c->name }}" required><input name="description" value="{{ $c->description }}" placeholder="Description"><button>Save</button></form>@endif</td><td>{{ $c->products_count }}</td><td class="{{ $c->is_active?'active':'inactive' }}">{{ $c->is_active?'Active':'Inactive' }}</td><td>@if(auth()->user()->hasPermission('products.edit'))<form method="POST" action="{{ route('catalog.categories.toggle',$c) }}">@csrf @method('PATCH')<button>{{ $c->is_active